## React

Summernote has no React package of its own. The community `react-summernote` wrapper asks for React 15, Bootstrap 3 and Summernote 0.8, so a React app on a current stack usually starts the jQuery plugin in an effect. Froala's wrapper is `react-froala-wysiwyg`, installed with the editor.

```shell
npm install froala-editor react-froala-wysiwyg
```

```jsx
// Summernote, the jQuery plugin in an effect
import { useEffect, useRef } from 'react';
import $ from 'jquery';
import 'summernote/dist/summernote-lite.min.css';
import 'summernote/dist/summernote-lite.min.js';

export default function Editor({ onChange }) {
  const ref = useRef(null);
  useEffect(() => {
    const $el = $(ref.current);
    $el.summernote({ callbacks: { onChange } });
    return () => $el.summernote('destroy');
  }, []);
  return <div ref={ref} />;
}
```

```jsx
// Froala
import { useState } from 'react';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';
import 'froala-editor/js/plugins.pkgd.min.js';
import FroalaEditorComponent from 'react-froala-wysiwyg';

const config = { key: 'YOUR_LICENSE_KEY' };

export default function Editor() {
  const [model, setModel] = useState('<p>Hello</p>');
  return (
    <FroalaEditorComponent tag="textarea" config={config} model={model} onModelChange={setModel} />
  );
}
```

