JAVASCRIPT

```
// Froala 5.5.0 — headless mode demo.
// The editor runs with no built-in UI. The toolbar below is our own HTML,
// and every button simply calls a Froala API method.

const outputEl = document.getElementById('output');

function showHTML(ed) {
  outputEl.textContent = ed.html.get();
}

// Ask the user for a URL. Returns the trimmed URL, or null if they cancel.
// (A browser prompt keeps this demo short. In your app, use your own input or dialog.)
function askForURL(message, example) {
  const url = window.prompt(message, example);
  return url && url.trim() ? url.trim() : null;
}

// ---------------------------------------------------------------------------
// 1. Create the editor in headless mode
// ---------------------------------------------------------------------------
const editor = new FroalaEditor('#editor', {
  // key: 'YOUR_LICENSE_KEY',   // add your license key here if you have one
  headless: true,               // no toolbar, popups or default styling
  htmlExecuteScripts: false,    // treat pasted scripts as plain content
  placeholderText: 'Start typing…',
  events: {
    initialized: function () {
      showHTML(this);
      buildToolbar(this);
    },
    contentChanged: function () {
      showHTML(this);
    },
    // Images and videos land asynchronously, so record the undo step once they arrive.
    'image.inserted': function () { this.undo.saveStep(); },
    'video.inserted': function () { this.undo.saveStep(); },
    // Froala's own error popups are off in headless mode, so report errors yourself.
    'image.error': function () { window.alert('That image could not be loaded.'); },
    'video.linkError': function () { window.alert('That link is not a supported YouTube or Vimeo URL.'); }
  }
});

// ---------------------------------------------------------------------------
// 2. Our own buttons. Each one calls a Froala API method.
//    inline: tag to check with format.is() for the pressed state
//    block:  tag to look for around the caret for the pressed state
//    history: undo/redo move through the history, so no extra undo step
//    async:   the undo step is saved when the media lands (see events above)
// ---------------------------------------------------------------------------
const GROUPS = [
  {
    label: 'Text',
    buttons: [
      { label: 'Bold', inline: 'strong', run: e => e.commands.bold() },
      { label: 'Italic', inline: 'em', run: e => e.commands.italic() },
      { label: 'Underline', inline: 'u', run: e => e.commands.underline() },
      { label: 'Strike', inline: 's', run: e => e.commands.strikeThrough() },
      { label: 'Sub', inline: 'sub', run: e => e.commands.subscript() },
      { label: 'Sup', inline: 'sup', run: e => e.commands.superscript() },
      { label: 'Clear format', run: e => e.commands.clearFormatting() }
    ]
  },
  {
    label: 'Blocks',
    buttons: [
      { label: 'Paragraph', run: e => e.paragraphFormat.apply('N') },
      { label: 'H2', block: 'h2', run: e => e.paragraphFormat.apply('H2') },
      { label: 'H3', block: 'h3', run: e => e.paragraphFormat.apply('H3') },
      { label: '• List', block: 'ul', run: e => e.lists.format('UL') },
      { label: '1. List', block: 'ol', run: e => e.lists.format('OL') },
      { label: 'Quote +', block: 'blockquote', run: e => e.quote.apply('increase') },
      { label: 'Quote −', run: e => e.quote.apply('decrease') },
      { label: 'Indent', run: e => e.commands.indent() },
      { label: 'Outdent', run: e => e.commands.outdent() },
      { label: 'Line', run: e => e.commands.insertHR() }
    ]
  },
  {
    label: 'Align',
    buttons: [
      { label: 'Left', run: e => e.align.apply('left') },
      { label: 'Center', run: e => e.align.apply('center') },
      { label: 'Right', run: e => e.align.apply('right') },
      { label: 'Justify', run: e => e.align.apply('justify') }
    ]
  },
  {
    label: 'Style',
    buttons: [
      { label: 'Red text', run: e => e.colors.text('#DC2626') },
      { label: 'Highlight', run: e => e.colors.background('#FDE68A') },
      { label: 'Size 24px', run: e => e.fontSize.apply('24px') },
      { label: 'Georgia', run: e => e.fontFamily.apply('Georgia,serif') },
      { label: 'Custom style', run: e => e.format.applyStyle('letter-spacing', '2px') }
    ]
  },
  {
    label: 'Insert',
    buttons: [
      {
        label: 'Link…', run: e => {
          const text = e.selection.text();
          e.selection.save();              // the prompt takes focus, so remember the selection
          const url = askForURL('Enter the link URL:', 'https://froala.com');
          e.selection.restore();
          if (!url) return;
          e.link.insert(url, text || url, { target: '_blank' });   // Froala adds rel="noopener noreferrer" itself
        }
      },
      {
        label: 'Image…', async: true, run: e => {
          e.selection.save();
          const url = askForURL('Enter the image URL:', 'https://picsum.photos/600/300');
          e.selection.restore();
          if (url) e.image.insertByURL(url);
        }
      },
      {
        label: 'Video…', async: true, run: e => {
          e.selection.save();
          const url = askForURL('Enter a YouTube or Vimeo link, for example https://www.youtube.com/watch?v=…', '');
          e.selection.restore();
          if (url) e.video.insertByURL(url);
        }
      },
      { label: 'Table 3×3', run: e => e.table.insert(3, 3) }
    ]
  },
  {
    label: 'History',
    buttons: [
      { label: 'Undo', history: true, run: e => e.commands.undo() },
      { label: 'Redo', history: true, run: e => e.commands.redo() },
      { label: 'Select all', history: true, run: e => e.commands.selectAll() }
    ]
  }
];

// ---------------------------------------------------------------------------
// 3. Build the toolbar HTML and wire up the clicks
// ---------------------------------------------------------------------------
function buildToolbar(ed) {
  const toolbar = document.getElementById('my-toolbar');
  toolbar.setAttribute('role', 'toolbar');
  toolbar.setAttribute('aria-label', 'Formatting');

  GROUPS.forEach(group => {
    const row = document.createElement('div');
    row.className = 'tb-group';
    row.innerHTML = '<span class="tb-label">' + group.label + '</span>';

    group.buttons.forEach(def => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'tb-btn';
      btn.textContent = def.label;
      if (def.inline) btn.dataset.inline = def.inline;
      if (def.block) btn.dataset.block = def.block;
      if (def.inline || def.block) btn.setAttribute('aria-pressed', 'false');

      // Keep the editor's text selection when the button is pressed
      // (Froala's own toolbar does the same thing).
      btn.addEventListener('mousedown', ev => ev.preventDefault());

      btn.addEventListener('click', () => {
        // commands.* methods record their own undo steps, but lists, align, paragraphFormat,
        // quote, colors, fontSize, fontFamily, link and table calls don't. So save a step
        // BEFORE the change (the state Undo returns to) and AFTER it (the state Redo returns to),
        // the same way Froala's own toolbar does. Froala ignores a step that matches the last one.
        // Undo/redo move through the history, and media saves its "after" step on insert.
        if (!def.history) ed.undo.saveStep();
        def.run(ed);
        if (!def.history && !def.async) ed.undo.saveStep();
        showHTML(ed);
        refreshActive(ed);
      });
      row.appendChild(btn);
    });

    toolbar.appendChild(row);
  });

  // Update pressed states when the caret moves or the content changes
  ['mouseup', 'keyup', 'contentChanged'].forEach(name => {
    ed.events.on(name, () => refreshActive(ed));
  });
}

function refreshActive(ed) {
  const el = ed.selection.element();

  document.querySelectorAll('.tb-btn[data-inline], .tb-btn[data-block]').forEach(btn => {
    let on;
    if (btn.dataset.inline) {
      on = ed.format.is(btn.dataset.inline);       // inline formatting, as in the guide
    } else {
      const match = el && el.closest ? el.closest(btn.dataset.block) : null;
      on = !!(match && ed.el.contains(match));     // block formatting around the caret
    }
    btn.classList.toggle('is-active', on);
    btn.setAttribute('aria-pressed', String(on));
  });
}
```

## How This Example Works

1.  **Create the editor** with `headless: true`. Froala turns `#editor` into an editable area.
2.  **Wait for `initialized`** before building the toolbar. Editor methods are ready from this moment on.
3.  **Describe buttons as data.** The `GROUPS` list pairs a label with a function, for example `e => e.commands.bold()`.
4.  **Keep the selection.** Calling `preventDefault()` on `mousedown` keeps the highlighted text selected while the user clicks your button.
5.  **Read the result** with `editor.html.get()` inside the `contentChanged` event.

## API methods used

[**commands.bold()**](https://froala.com/wysiwyg-editor/docs/methods/#commands.bold)

Also `italic()`, `underline()`, `strikeThrough()`, `clearFormatting()`, `insertHR()`, `undo()`, `redo()`.

[**paragraphFormat.apply()**](https://froala.com/wysiwyg-editor/docs/methods/#paragraphFormat.apply)

Sets the block type. Accepts `'N'` (normal), `'H2'`, `'H3'` and more.

[**quote.apply()**](https://froala.com/wysiwyg-editor/docs/methods/#quote.apply)

Pass `'increase'` to wrap blocks in a blockquote.

[**lists.format()**](https://froala.com/wysiwyg-editor/docs/methods/#lists.format)

Pass `'UL'` for bullets or `'OL'` for numbers.

[**align.apply()**](https://froala.com/wysiwyg-editor/docs/methods/#align.apply)

`'left'`, `'center'`, `'right'` or `'justify'`.

[**link.insert()**](https://froala.com/wysiwyg-editor/docs/methods/#link.insert)

Inserts a link with `(href, text)`.

[**table.insert()**](https://froala.com/wysiwyg-editor/docs/methods/#table.insert)

Inserts a table with `(rows, columns)`.

[**html.get()**](https://froala.com/wysiwyg-editor/docs/methods/#html.get)

Returns the current content as an HTML string.

## Learn the full setup

This example shows headless mode in one working page. The [headless editor setup guide](https://froala.com/wysiwyg-editor/docs/concepts/custom/headless-editor/) explains each piece step by step and covers what a production app needs.

-   **React setup** with the official Froala wrapper.
-   **Styling the editing area** with your own CSS.
-   **Saving and loading content** with `html.get()` and `html.set()`.
-   **Everything that changes** when `headless` is set to `true`.
-   **Helper methods** for making your own plugins work in headless mode.

**Read the [headless editor setup guide](https://froala.com/wysiwyg-editor/docs/concepts/custom/headless-editor/)**

# Image Styles in Froala Editor

## Image Styles

While using the `image.min.js` plugin it is possible to add custom style on the selected image inside the WYSIWYG HTML editor.

### Try it yourself:



You can define your own image styles using the `[imageStyles](https://froala.com/wysiwyg-editor/docs/options#imageStyles "imageStyles")` option. This option is an Object where the key represents the class name and its value is the style name that appears in the dropdown list. It is important to have unique keys otherwise they will not work properly.

By default you can select multiple image styles at a time. If you want to toggle them and allow only one style to be selected at a time use the `[imageMultipleStyles](https://froala.com/wysiwyg-editor/docs/options#imageMultipleStyles "imageMultipleStyles")` option.

[Edit in JSFiddle](https://jsfiddle.net/froala/2pL9hsfg/ "Edit Image Styles in JSFiddle")

